package kubeadm

import (
	"encoding/base64"
	"fmt"
	"testing"

	"github.com/stretchr/testify/assert"
)

// caPEM is the raw PEM of the CA certificate as embedded in the generated
// kubeconfigs on the itx-kamaji tenant.
const caPEM = ""

// caTextDump is the same CA certificate stored as an openssl x509 -text
// dump, which is how it is stored in the CA secret on the itx-kamaji tenant.
const caTextDump = ""

func TestIsKubeconfigCAValid(t *testing.T) {
	caPEMBytes := mustBase64Decode(t, caPEM)
	caTextDumpBytes := mustBase64Decode(t, caTextDump)

	t.Run("ca stored as openssl x509 -text dump", func(t *testing.T) {
		kc := buildKubeconfigWithCA(t, caPEMBytes)
		assert.True(t, IsKubeconfigCAValid(kc, caTextDumpBytes))
	})

	t.Run("ca stored as clean PEM", func(t *testing.T) {
		kc := buildKubeconfigWithCA(t, caPEMBytes)
		assert.True(t, IsKubeconfigCAValid(kc, caPEMBytes))
	})

	t.Run("empty ca", func(t *testing.T) {
		kc := buildKubeconfigWithCA(t, caPEMBytes)
		assert.False(t, IsKubeconfigCAValid(kc, nil))
	})

	t.Run("mismatched ca", func(t *testing.T) {
		kc := buildKubeconfigWithCA(t, caPEMBytes)
		otherPEM := mustBase64Decode(t, "")
		assert.False(t, IsKubeconfigCAValid(kc, otherPEM))
	})
}

func buildKubeconfigWithCA(t *testing.T, caPEM []byte) []byte {
	t.Helper()

	return []byte(fmt.Sprintf(`apiVersion: v1
kind: Config
clusters:
- name: test
  cluster:
    certificate-authority-data: %s
    server: https://127.0.0.1:6443
contexts:
- name: test
  context:
    cluster: test
    user: test
current-context: test
users:
- name: test
  user: {}
`, base64.StdEncoding.EncodeToString(caPEM)))
}

func mustBase64Decode(t *testing.T, s string) []byte {
	t.Helper()

	data, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		t.Fatalf("cannot decode fixture: %v", err)
	}

	return data
}
